// Collection-oriented — no save() needed
public interface OrderRepository {
    void add(Order order);          // insert only
    Optional<Order> findById(OrderId id);
    void remove(Order order);       // delete
}

// Persistence-oriented — explicit save for updates too
public interface OrderRepository {
    void save(Order order);         // insert or update
    Optional<Order> findById(OrderId id);
    void delete(OrderId id);
}

public interface CustomerRepository {

    // Retrieve by primary identity
    Optional<Customer> findById(CustomerId id);

    // Insert new or update existing aggregate
    Customer save(Customer customer);

    // Hard delete (soft-delete is a domain decision, not a repo one)
    void delete(CustomerId id);

    // Aggregate count — useful for validation rules
    long count();

    // Existence check without full hydration
    boolean existsById(CustomerId id);
}

// Domain layer — Specification interface
public interface Specification<T> {
    boolean isSatisfiedBy(T candidate);

    default Specification<T> and(Specification<T> other) {
        return candidate ->
            this.isSatisfiedBy(candidate) && other.isSatisfiedBy(candidate);
    }

    default Specification<T> or(Specification<T> other) {
        return candidate ->
            this.isSatisfiedBy(candidate) || other.isSatisfiedBy(candidate);
    }

    default Specification<T> not() {
        return candidate -> !this.isSatisfiedBy(candidate);
    }
}

// Concrete specification — named after domain concept
public class ActiveCustomerSpec implements Specification<Customer> {
    @Override
    public boolean isSatisfiedBy(Customer c) {
        return c.isActive() && !c.isBlacklisted();
    }
}

// Repository accepting a specification
public interface CustomerRepository {
    List<Customer> findSatisfying(Specification<Customer> spec);
}

// Call site — composes specifications
Specification<Customer> eligibleForPromo =
    new ActiveCustomerSpec().and(new PremiumTierSpec());
List<Customer> targets = customerRepository.findSatisfying(eligibleForPromo);

// Domain layer — pure interface, no ORM imports
public interface OrderRepository {
    Optional<Order> findById(OrderId id);
    List<Order> findPendingShipment();
    Order save(Order order);
}

// Infrastructure layer — delegates to Spring Data JPA
@Repository
public class JpaOrderRepository implements OrderRepository {

    private final OrderJpaRepository jpa; // extends JpaRepository

    @Override
    public Optional<Order> findById(OrderId id) {
        return jpa.findById(id.value()).map(OrderMapper::toDomain);
    }

    @Override
    public List<Order> findPendingShipment() {
        return jpa.findByStatus("PENDING_SHIPMENT")
                  .stream()
                  .map(OrderMapper::toDomain)
                  .toList();
    }
}

public class InMemoryOrderRepository implements OrderRepository {

    private final Map<OrderId, Order> store = new HashMap<>();

    @Override
    public Optional<Order> findById(OrderId id) {
        return Optional.ofNullable(store.get(id));
    }

    @Override
    public Order save(Order order) {
        store.put(order.id(), order);
        return order;
    }

    @Override
    public void delete(OrderId id) {
        store.remove(id);
    }

    @Override
    public List<Order> findPendingShipment() {
        return store.values().stream()
                    .filter(o -> o.status() == OrderStatus.PENDING_SHIPMENT)
                    .toList();
    }

    // Test helper — not part of the domain interface
    public Collection<Order> findAll() {
        return Collections.unmodifiableCollection(store.values());
    }
}

public interface CustomerRepository {
    Optional<Customer> findById(CustomerId id);
    Customer save(Customer customer);

    // Domain-named finders
    List<Customer> findActiveCustomersOver18();
    List<Customer> findEligibleForLoyaltyUpgrade();
    Optional<Customer> findByEmailAddress(EmailAddress email);
    List<Customer> findWithExpiredSubscriptions(LocalDate asOf);
}

public interface OrderRepository {

    // Offset pagination — simple, Spring Data-friendly
    Page<Order> findPendingShipment(Pageable pageable);

    // Cursor pagination — stable, scalable
    List<Order> findCreatedAfter(OrderId lastSeen, int limit);
}

// Write side — uses Repository for command processing
public class CancelOrderHandler {
    private final OrderRepository orders;

    public void handle(CancelOrderCommand cmd) {
        Order order = orders.findById(cmd.orderId()).orElseThrow();
        order.cancel(cmd.reason());
        orders.save(order);
    }
}

// Read side — bypasses Repository, reads projection directly
public class OrderSummaryQuery {
    private final OrderReadStore readStore; // hits a denormalized table

    public List<OrderSummaryDto> findByCustomer(CustomerId customerId) {
        return readStore.queryByCustomerId(customerId.value());
    }
}

